python3 -c "
from html.parser import HTMLParser

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
        self.void_elements = {'br','hr','img','input','meta','link','area','base','col','embed','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'Mismatched tag: </{tag}>, expected </{self.stack[-1] if self.stack else \"?\"}>') 

v = Validator()
with open('/app/output/final_report.html', 'r') as f:
    v.feed(f.read())
if v.errors:
    for e in v.errors:
        print(e)
elif v.stack:
    print(f'Unclosed tags: {v.stack}')
else:
    print('HTML structure valid')
print(f'File size: {__import__(\"os\").path.getsize(\"/app/output/final_report.html\")} bytes')
"

